#include <zephyr/ztest.h>
#include <zephyr/drivers/counter.h>
#include <zephyr/devicetree.h>
#include <zephyr/kernel.h>
#include <zephyr/logging/log.h>

LOG_MODULE_REGISTER(counter_capture_test, CONFIG_COUNTER_LOG_LEVEL);

/* Define a common test structure or context for the suite */
struct counter_capture_test_data {
	const struct device *dev;
	uint32_t max_top_value;
	uint32_t ticks_per_sec;
	uint32_t prescaler;
	uint32_t freq;
	uint8_t channel_id; /* Current channel being tested */
	struct k_sem capture_sem;
	uint32_t captured_ticks;
	bool capture_done;
};

static struct counter_capture_test_data test_data;

/* Callback for capture events */
static void capture_callback(const struct device *dev, uint8_t chan_id, uint32_t ticks, void *user_data)
{
	struct counter_capture_test_data *data = (struct counter_capture_test_data *)user_data;
	LOG_DBG("Capture on channel %d: %u ticks", chan_id, ticks);
	data->captured_ticks = ticks;
	data->capture_done = true;
	k_sem_give(&data->capture_sem);
}

/* Helper functions for ZTEST_SUITE */
static void counter_setup(void)
{
	/* Common setup for the entire test suite */
	/* Assuming a single counter instance for simplicity, or the first one. */
	/* The actual test might iterate over multiple instances. */
	/* Using DT_ALIAS(counter_0) as a common pattern for a default counter. */
	test_data.dev = DEVICE_DT_GET(DT_ALIAS(counter_0));
	zassert_true(device_is_ready(test_data.dev), "Counter device not ready");

	struct counter_capabilities cap;
	counter_get_capabilities(test_data.dev, &cap);
	test_data.max_top_value = cap.max_top_value;
	test_data.ticks_per_sec = cap.ticks_per_sec;
	test_data.prescaler = cap.prescaler;
	test_data.freq = cap.freq;

	k_sem_init(&test_data.capture_sem, 0, 1); /* Initialize semaphore for capture events */
}

static void counter_before(void)
{
	/* Setup before each test case */
	/* Reset counter to a known state, clear capture flags */
	zassert_equal(counter_stop(test_data.dev), 0, "Failed to stop counter");
	zassert_equal(counter_set_top_value(test_data.dev, test_data.max_top_value, 0), 0, "Failed to set top value");
	zassert_equal(counter_start(test_data.dev), 0, "Failed to start counter");
	test_data.capture_done = false;
	k_sem_reset(&test_data.capture_sem);
}

static void counter_after(void)
{
	/* Teardown after each test case */
	/* e.g., stop counter, disable capture channels */
	zassert_equal(counter_stop(test_data.dev), 0, "Failed to stop counter");
	/* Unset capture callback if set in the test case to clean up */
	struct counter_config_capture cfg = {
		.channel_id = test_data.channel_id,
		.callback = NULL,
		.user_data = NULL,
		.flags = 0,
	};
	(void)counter_capture_set_callback(test_data.dev, &cfg); /* Best effort cleanup */
}

static void counter_teardown(void)
{
	/* Common teardown for the entire test suite */
	/* No specific teardown needed for this example beyond what counter_after does */
}

/* Test cases */

/* Define a placeholder compatible for the test device. */
/* This should match a compatible in your devicetree for the counter(s) you want to test. */
#define DT_DRV_COMPAT zephyr_counter_capture_test_device

/* Macro to define a test case for each instance of the compatible device */
#define DEFINE_CAPTURE_TEST_CASE(inst) \
	ZTEST(counter_capture, test_capture_inst_##inst) \
	{ \
		const struct device *dev = DEVICE_DT_GET(DT_DRV_INST(inst)); \
		zassert_true(device_is_ready(dev), "Counter device %s not ready", DT_NODE_PATH(DT_DRV_INST(inst))); \
		\
		/* Assuming channel 0 for simplicity, but could be iterated or configured via DT */ \
		uint8_t channel_id = 0; \
		test_data.channel_id = channel_id; \
		\
		struct counter_config_capture cfg = { \
			.channel_id = channel_id, \
			.callback = capture_callback, \
			.user_data = &test_data, \
			.flags = 0, \
		}; \
		\
		int ret = counter_capture_set_callback(dev, &cfg); \
		zassert_equal(ret, 0, "Failed to set capture callback for %s, channel %d", \
			      DT_NODE_PATH(DT_DRV_INST(inst)), channel_id); \
		\
		ret = counter_capture_start(dev, channel_id); \
		zassert_equal(ret, 0, "Failed to start capture for %s, channel %d", \
			      DT_NODE_PATH(DT_DRV_INST(inst)), channel_id); \
		\
		/* Simulate some counter activity or wait for capture trigger */ \
		/* In a real test, this would involve triggering the capture event (e.g., GPIO pulse) */ \
		k_sleep(K_MSEC(100)); \
		\
		/* Wait for the capture callback to signal */ \
		ret = k_sem_take(&test_data.capture_sem, K_MSEC(500)); \
		zassert_equal(ret, 0, "Capture callback did not fire in time"); \
		zassert_true(test_data.capture_done, "Capture callback flag not set"); \
		\
		LOG_INF("Captured ticks: %u", test_data.captured_ticks); \
		/* Add assertions on captured_ticks if expected values are known */ \
		\
		ret = counter_capture_stop(dev, channel_id); \
		zassert_equal(ret, 0, "Failed to stop capture for %s, channel %d", \
			      DT_NODE_PATH(DT_DRV_INST(inst)), channel_id); \
	}

/* Generate test cases for each instance of the compatible device */
DT_INST_FOREACH_STATUS_OKAY(DEFINE_CAPTURE_TEST_CASE)

/* Define a basic test case for general functionality if no instances are found or for a default counter */
ZTEST(counter_capture, test_basic_capture)
{
	const struct device *dev = test_data.dev;
	uint8_t channel_id = 0;
	test_data.channel_id = channel_id;

	struct counter_config_capture cfg = {
		.channel_id = channel_id,
		.callback = capture_callback,
		.user_data = &test_data,
		.flags = 0,
	};

	int ret = counter_capture_set_callback(dev, &cfg);
	zassert_equal(ret, 0, "Failed to set capture callback");

	ret = counter_capture_start(dev, channel_id);
	zassert_equal(ret, 0, "Failed to start capture");

	k_sleep(K_MSEC(100)); /* Simulate some activity */

	ret = k_sem_take(&test_data.capture_sem, K_MSEC(500));
	zassert_equal(ret, 0, "Capture callback did not fire in time");
	zassert_true(test_data.capture_done, "Capture callback flag not set");

	LOG_INF("Basic captured ticks: %u", test_data.captured_ticks);

	ret = counter_capture_stop(dev, channel_id);
	zassert_equal(ret, 0, "Failed to stop capture");
}

/* Define the test suite with the helper functions */
ZTEST_SUITE(counter_capture, counter_setup, counter_before, counter_after, counter_teardown, NULL);
